```ts
async function getJson<T>(url: string, parse: (d: unknown) => T): Promise<T> {
  try {
    const res = await fetch(url);
    return parse(await res.json());
  } catch {
    // treat any failure as "no data"
    return undefined as T;
  }
}
```

