Requirements for `deepClone<T>(value: T): T`: copy nested plain objects and arrays so that no reference is shared, handle `null` values, and keep properties whose value is `undefined` (so `"note" in copy` stays `true`). Which implementation meets every requirement?

```ts
function clone1<T>(value: T): T {
  return JSON.parse(JSON.stringify(value));
}

function clone2<T>(value: T): T {
  if (typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map(clone2) as T;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as object)) out[k] = clone2(v);
  return out as T;
}

function clone3<T>(value: T): T {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map(clone3) as T;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value)) out[k] = clone3(v);
  return out as T;
}

function clone4<T extends object>(value: T): T {
  return { ...value };
}
```

This `deepEqual` passes the interviewer's first few tests:

```ts
function deepEqual<T>(a: T, b: T): boolean {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) {
    return false;
  }
  for (const key of Object.keys(a)) {
    if (!deepEqual((a as any)[key], (b as any)[key])) return false;
  }
  return true;
}
```

